		[OpenTpwText.ProgressKeysNeeded] = new[] { "This theme needs {0} keys. You have {1}. Choose Instant Action or load a saved park.", "Dette tema kræver {0} nøgler. Du har {1}. Vælg Instant Action eller indlæs en gemt park.", "Dit thema vereist {0} sleutels. Je hebt er {1}. Kies Instant Action of laad een opgeslagen park.", "Ce thème nécessite {0} clés. Vous en avez {1}. Choisissez Instant Action ou chargez un parc.", "Dieses Thema benötigt {0} Schlüssel. Du hast {1}. Wähle Instant Action oder lade einen Park.", "이 테마에는 열쇠 {0}개가 필요합니다. 현재 {1}개입니다. 인스턴트 액션을 고르거나 저장한 공원을 불러오십시오.", "Ten temat wymaga kluczy: {0}. Masz: {1}. Wybierz Szybką akcję lub wczytaj zapisany park.", "Este tema necesita {0} llaves. Tienes {1}. Elige Acción Instantánea o carga un parque guardado.", "Detta tema kräver {0} nycklar. Du har {1}. Välj Instant Action eller läs in en sparad park." },
		[OpenTpwText.ProgressModeKept] = new[] { "Your Instant Action progress will not be reset. Choose Instant Action or load a saved park.", "Dine Instant Action-fremskridt nulstilles ikke. Vælg Instant Action eller indlæs en gemt park.", "Je Instant Action-voortgang wordt niet gewist. Kies Instant Action of laad een opgeslagen park.", "Votre progression Instant Action sera conservée. Choisissez Instant Action ou chargez un parc.", "Dein Instant Action-Fortschritt bleibt erhalten. Wähle Instant Action oder lade einen Park.", "인스턴트 액션 진행은 초기화되지 않습니다. 인스턴트 액션을 고르거나 저장한 공원을 불러오십시오.", "Twój postęp w Szybkiej akcji nie zostanie wyzerowany. Wybierz Szybką akcję lub wczytaj zapisany park.", "Tu progreso de Acción Instantánea no se reiniciará. Elige Acción Instantánea o carga un parque guardado.", "Dina Instant Action-framsteg behålls. Välj Instant Action eller läs in en sparad park." },
		[OpenTpwText.ProgressActionFailed] = new[] { "The action could not finish. Saved parks are unchanged. Reopen the choice or retry.", "Handlingen kunne ikke fuldføres. Gemte parker er uændrede. Åbn valget igen eller prøv igen.", "De actie kon niet worden voltooid. Opgeslagen parken zijn ongewijzigd. Open de keuze opnieuw of probeer opnieuw.", "Impossible de terminer. Les parcs sauvegardés sont inchangés. Rouvrez le choix ou réessayez.", "Die Aktion konnte nicht beendet werden. Gespeicherte Parks sind unverändert. Öffne die Auswahl erneut oder versuche es noch einmal.", "작업을 끝내지 못했습니다. 저장한 공원은 그대로입니다. 선택을 다시 열거나 다시 시도하십시오.", "Nie udało się wykonać akcji. Zapisane parki się nie zmieniły. Otwórz wybór ponownie lub spróbuj jeszcze raz.", "No se pudo completar la acción. Los parques guardados no han cambiado. Vuelve a abrir la opción o inténtalo de nuevo.", "Åtgärden kunde inte slutföras. Sparade parker är oförändrade. Öppna valet igen eller försök igen." },
		[OpenTpwText.ProgressUnsaved] = new[] { "Progress is not saved yet. Earned tickets are kept in memory. Retry before leaving the park.", "Fremskridt er ikke gemt endnu. Optjente billetter er bevaret i hukommelsen. Prøv igen før du forlader parken.", "Voortgang is nog niet opgeslagen. Verdiende tickets blijven in het geheugen. Probeer opnieuw voordat je het park verlaat.", "La progression n'est pas encore sauvegardée. Les tickets gagnés sont conservés en mémoire. Réessayez avant de quitter le parc.", "Der Fortschritt ist noch nicht gespeichert. Verdiente Tickets bleiben im Speicher. Versuche es erneut, bevor du den Park verlässt.", "진행이 아직 저장되지 않았습니다. 얻은 티켓은 메모리에 있습니다. 공원을 나가기 전에 다시 시도하십시오.", "Postęp nie jest jeszcze zapisany. Zdobyte bilety są w pamięci. Spróbuj ponownie przed wyjściem z parku.", "El progreso aún no se ha guardado. Los billetes ganados se mantienen en memoria. Inténtalo de nuevo antes de salir del parque.", "Framstegen är inte sparade ännu. Intjänade biljetter finns kvar i minnet. Försök igen innan du lämnar parken." },
		[OpenTpwText.ProgressTrackingUnavailable] = new[] { "OpenTPW progress is not tracking this park. Past player history is unknown or uses another mode. Existing saved parks remain playable.", "OpenTPW-fremskridt registrerer ikke denne park. Tidligere spillerhistorik er ukendt eller bruger en anden tilstand. Gemte parker kan stadig spilles.", "OpenTPW-voortgang wordt niet bijgehouden voor dit park. Eerdere spelergeschiedenis is onbekend of gebruikt een andere modus. Opgeslagen parken blijven speelbaar.", "OpenTPW ne suit pas la progression de ce parc. L'historique du joueur est inconnu ou utilise un autre mode. Les parcs sauvegardés restent jouables.", "OpenTPW erfasst den Fortschritt dieses Parks nicht. Der bisherige Verlauf ist unbekannt oder nutzt einen anderen Modus. Gespeicherte Parks bleiben spielbar.", "OpenTPW가 이 공원의 진행을 기록하지 않습니다. 이전 플레이어 기록을 알 수 없거나 다른 모드입니다. 저장한 공원은 계속 할 수 있습니다.", "OpenTPW nie śledzi postępu w tym parku. Historia gracza jest nieznana lub używa innego trybu. Zapisane parki nadal działają.", "OpenTPW no registra el progreso de este parque. Se desconoce el historial anterior del jugador o usa otro modo. Los parques guardados se pueden seguir jugando.", "OpenTPW registrerar inte framsteg för denna park. Tidigare spelarhistorik är okänd eller använder ett annat läge. Sparade parker kan fortfarande spelas." },
		[OpenTpwText.ContinueAutomaticPark] = new[] { "Continue automatic save", "Fortsæt automatisk gemt park", "Automatisch opgeslagen park hervatten", "Continuer la sauvegarde automatique", "Automatischen Spielstand fortsetzen", "자동 저장 계속", "Kontynuuj zapis automatyczny", "Continuar guardado automático", "Fortsätt automatisk sparning" },
		[OpenTpwText.AutomaticCheckpointFailed] = new[] { "The automatic save could not finish. Stay in the park or retry.", "Den automatiske gemning mislykkedes. Bliv i parken eller prøv igen.", "Automatisch opslaan is mislukt. Blijf in het park of probeer opnieuw.", "La sauvegarde automatique a échoué. Restez dans le parc ou réessayez.", "Automatisches Speichern fehlgeschlagen. Bleibe im Park oder versuche es erneut.", "자동 저장을 끝내지 못했습니다. 공원에 머물거나 다시 시도하십시오.", "Nie udało się wykonać zapisu automatycznego. Zostań w parku lub spróbuj jeszcze raz.", "No se pudo completar el guardado automático. Quédate en el parque o inténtalo de nuevo.", "Den automatiska sparningen misslyckades. Stanna i parken eller försök igen." },
		[OpenTpwText.RetryCheckpoint] = new[] { "Retry", "Prøv igen", "Opnieuw proberen", "Réessayer", "Erneut versuchen", "다시 시도", "Ponów", "Reintentar", "Försök igen" },
