		[OpenTpwText.MapNoObservations] = new[] { "No observations yet", "Ingen observationer endnu", "Nog geen waarnemingen", "Aucune observation pour le moment", "Noch keine Beobachtungen", "아직 관찰 기록 없음", "Brak obserwacji", "Aún sin observaciones", "Inga observationer ännu" },
