		[OpenTpwText.OpenTpwPage] = new[] { "OpenTPW", "OpenTPW", "OpenTPW", "OpenTPW", "OpenTPW", "OpenTPW", "OpenTPW", "OpenTPW", "OpenTPW" },
		// [DATA:video 15:20] the Dutch line is the original's own help text of a tube message; the other five languages are translated from it
		[OpenTpwText.MessageTubeHelp] = new[] { "Message - left-click to open, right-click to delete", "Besked - venstreklik for at åbne, højreklik for at slette", "Bericht - klik links om te openen, klik rechts om te verwijderen", "Message - clic gauche pour ouvrir, clic droit pour supprimer", "Nachricht - Linksklick zum Öffnen, Rechtsklick zum Löschen", "메시지 - 왼쪽 클릭: 열기, 오른쪽 클릭: 삭제", "Wiadomość - LPM, aby otworzyć, PPM, aby usunąć", "Mensaje - clic izquierdo para abrir, clic derecho para borrar", "Meddelande - vänsterklicka för att öppna, högerklicka för att ta bort" },
		[OpenTpwText.BuyLandHint] = new[] { "Click two opposite corners of the land to buy; right click to cancel.", "Klik på to modsatte hjørner af grunden, du vil købe; højreklik for at annullere.", "Klik op twee tegenoverliggende hoeken van het land dat je wilt kopen; klik met rechts om te annuleren.", "Cliquez sur deux coins opposés du terrain à acheter ; clic droit pour annuler.", "Klicke auf zwei gegenüberliegende Ecken des Landes, das du kaufen willst; Rechtsklick bricht ab.", "구입할 부지의 대각 모서리 두 곳을 클릭하십시오. 오른쪽 클릭하면 취소됩니다.", "Kliknij dwa przeciwległe rogi gruntu do kupienia; PPM anuluje.", "Haz clic en dos esquinas opuestas del terreno que quieres comprar; clic derecho para cancelar.", "Klicka på två motsatta hörn av marken du vill köpa; högerklicka för att avbryta." },
		[OpenTpwText.CannotBuyLand] = new[] { "You cannot buy this land.", "Du kan ikke købe denne grund.", "Je kunt dit land niet kopen.", "Vous ne pouvez pas acheter ce terrain.", "Dieses Land kannst du nicht kaufen.", "이 부지는 구입할 수 없습니다.", "Nie możesz kupić tego gruntu.", "No puedes comprar este terreno.", "Du kan inte köpa den här marken." },
		// [EXT:pools-ui] the pool tool of the opentpw.pools extension
		[OpenTpwText.PoolRowPaint] = new[] { "Pool water", "Poolvand", "Zwembadwater", "Eau de piscine", "Poolwasser", "수영장 물", "Woda basenowa", "Agua de piscina", "Poolvatten" },
		[OpenTpwText.PoolRowErase] = new[] { "Remove pool water", "Fjern poolvand", "Zwembadwater verwijderen", "Retirer l'eau de piscine", "Poolwasser entfernen", "수영장 물 제거", "Usuń wodę basenową", "Quitar agua de piscina", "Ta bort poolvatten" },
		[OpenTpwText.PoolPaintHelp] = new[] { "Click and drag to paint pool water on level, empty land you own.", "Klik og træk for at male poolvand på jævn, tom grund, du ejer.", "Klik en sleep om zwembadwater te schilderen op vlak, leeg land dat je bezit.", "Cliquez et faites glisser pour peindre de l'eau de piscine sur un terrain plat, vide et à vous.", "Klicken und ziehen, um Poolwasser auf ebenes, leeres Land in deinem Besitz zu malen.", "클릭하고 끌어서 소유한 평평한 빈 땅에 수영장 물을 칠하십시오.", "Kliknij i przeciągnij, aby namalować wodę basenową na płaskim, pustym gruncie, który posiadasz.", "Haz clic y arrastra para pintar agua de piscina en terreno llano, vacío y tuyo.", "Klicka och dra för att måla poolvatten på jämn, tom mark som du äger." },
		[OpenTpwText.PoolEraseHelp] = new[] { "Click and drag to remove pool water; you get the money back.", "Klik og træk for at fjerne poolvand; du får pengene tilbage.", "Klik en sleep om zwembadwater te verwijderen; je krijgt het geld terug.", "Cliquez et faites glisser pour retirer l'eau de piscine ; l'argent vous est rendu.", "Klicken und ziehen, um Poolwasser zu entfernen; das Geld wird erstattet.", "클릭하고 끌어서 수영장 물을 제거하십시오. 돈이 환불됩니다.", "Kliknij i przeciągnij, aby usunąć wodę basenową; pieniądze wracają do ciebie.", "Haz clic y arrastra para quitar agua de piscina; te devuelven el dinero.", "Klicka och dra för att ta bort poolvatten; du får pengarna tillbaka." },
		[OpenTpwText.PoolPaintHint] = new[] { "Pool water: press and drag over empty land to paint it; right click to stop.", "Poolvand: tryk og træk over tom grund for at male; højreklik for at stoppe.", "Zwembadwater: houd ingedrukt en sleep over leeg land om te schilderen; klik met rechts om te stoppen.", "Eau de piscine : appuyez et faites glisser sur un terrain vide pour peindre ; clic droit pour arrêter.", "Poolwasser: auf leerem Land drücken und ziehen, um zu malen; Rechtsklick beendet.", "수영장 물: 빈 땅 위에서 누른 채 끌어서 칠하십시오. 오른쪽 클릭하면 멈춥니다.", "Woda basenowa: naciśnij i przeciągnij po pustym gruncie, aby malować; PPM kończy.", "Agua de piscina: pulsa y arrastra sobre terreno vacío para pintar; clic derecho para parar.", "Poolvatten: tryck och dra över tom mark för att måla; högerklicka för att sluta." },
		[OpenTpwText.PoolEraseHint] = new[] { "Remove pool water: press and drag over pool cells; right click to stop.", "Fjern poolvand: tryk og træk over poolfelter; højreklik for at stoppe.", "Zwembadwater verwijderen: houd ingedrukt en sleep over zwembadvakjes; klik met rechts om te stoppen.", "Retirer l'eau de piscine : appuyez et faites glisser sur les cases d'eau ; clic droit pour arrêter.", "Poolwasser entfernen: über Poolfelder drücken und ziehen; Rechtsklick beendet.", "수영장 물 제거: 수영장 칸 위에서 누른 채 끄십시오. 오른쪽 클릭하면 멈춥니다.", "Usuń wodę basenową: naciśnij i przeciągnij po polach basenu; PPM kończy.", "Quitar agua de piscina: pulsa y arrastra sobre las casillas de piscina; clic derecho para parar.", "Ta bort poolvatten: tryck och dra över poolrutor; högerklicka för att sluta." },
		[OpenTpwText.PoolTooSteep] = new[] { "The ground is too steep for a pool here", "Jorden er for skrå til en pool her", "De grond is hier te steil voor een zwembad", "Le terrain est trop pentu pour une piscine ici", "Der Boden ist hier zu steil für einen Pool", "이곳은 지면이 너무 가팔라 수영장을 만들 수 없습니다", "Teren jest tu zbyt stromy na basen", "El terreno es demasiado empinado para una piscina aquí", "Marken är för brant för en pool här" },
		// [EXT:pools-swim] the swim session's guest states and the changing room's refusals
		[OpenTpwText.PoolStateSwimming] = new[] { "Swimming", "Svømmer", "Zwemt", "Nage", "Schwimmt", "수영 중", "Pływa", "Nadando", "Simmar" },
		[OpenTpwText.PoolStateClimbingOut] = new[] { "Climbing out of the pool", "Kravler op af poolen", "Klimt uit het zwembad", "Sort de la piscine", "Steigt aus dem Pool", "수영장에서 나오는 중", "Wychodzi z basenu", "Saliendo de la piscina", "Klättrar upp ur poolen" },
		[OpenTpwText.PoolStateChanging] = new[] { "Changing", "Skifter tøj", "Kleedt zich om", "Se change", "Zieht sich um", "옷을 갈아입는 중", "Przebiera się", "Cambiándose", "Byter om" },
		[OpenTpwText.PoolSwimmersInWater] = new[] { "Swimmers are in the water here", "Der er svømmere i vandet her", "Er zwemmers in het water hier", "Des nageurs sont dans l'eau ici", "Hier sind Schwimmer im Wasser", "이곳 물속에 수영하는 사람이 있습니다", "W wodzie są pływacy", "Hay nadadores en el agua aquí", "Det finns simmare i vattnet här" },
		[OpenTpwText.PoolChangingRoomNeedsWater] = new[] { "A changing room needs this pool water", "Et omklædningsrum har brug for dette poolvand", "Een kleedkamer heeft dit zwembadwater nodig", "Un vestiaire a besoin de cette eau de piscine", "Eine Umkleide braucht dieses Poolwasser", "탈의실에 이 수영장 물이 필요합니다", "Przebieralnia potrzebuje tej wody basenowej", "Un vestuario necesita esta agua de piscina", "Ett omklädningsrum behöver det här poolvattnet" },
		[OpenTpwText.PoolExtraNeedsEdge] = new[] { "A pool object needs a straight pool edge (a shower needs a changing room, a lounger or lamp needs water beside it)", "Et poolobjekt kræver en lige poolkant (et brusebad kræver et omklædningsrum, en liggestol eller lampe kræver vand ved siden af)", "Een zwembadobject heeft een rechte zwembadrand nodig (een douche een kleedkamer, een ligbed of lamp water ernaast)", "Un objet de piscine exige un bord droit (une douche un vestiaire, une chaise longue ou une lampe de l'eau à côté)", "Ein Poolobjekt braucht einen geraden Poolrand (eine Dusche eine Umkleide, eine Liege oder Lampe Wasser daneben)", "수영장 물건에는 곧은 수영장 가장자리가 필요합니다 (샤워기는 탈의실, 선베드와 조명은 옆에 물이 필요)", "Obiekt basenowy wymaga prostej krawędzi basenu (prysznic przebieralni, leżak lub lampa wody obok)", "Un objeto de piscina necesita un borde recto (una ducha un vestuario, una tumbona o lámpara agua al lado)", "Ett poolobjekt behöver en rak poolkant (en dusch ett omklädningsrum, en solstol eller lampa vatten bredvid)" },
		[OpenTpwText.PoolExtraNeedsWater] = new[] { "A pool object needs this pool water", "Et poolobjekt har brug for dette poolvand", "Een zwembadobject heeft dit zwembadwater nodig", "Un objet de piscine a besoin de cette eau de piscine", "Ein Poolobjekt braucht dieses Poolwasser", "수영장 물건에 이 수영장 물이 필요합니다", "Obiekt basenowy potrzebuje tej wody basenowej", "Un objeto de piscina necesita esta agua de piscina", "Ett poolobjekt behöver det här poolvattnet" },
		// [EXT:pools-slides] a splash cell with riders on it, or the foot of a tower's stairs with guests on them, cannot be erased
		[OpenTpwText.PoolSlideRiders] = new[] { "A slide has guests on it here", "En vandrutsjebane har gæster på sig her", "Er zijn gasten op een glijbaan hier", "Des clients sont sur un toboggan ici", "Hier sind Gäste auf einer Rutsche", "여기 물 미끄럼틀에 손님이 있습니다", "Na zjeżdżalni są tu goście", "Hay clientes en un tobogán aquí", "Det finns gäster på en rutschkana här" },
		// [EXT:pools-slides] the slide row, the tool's hints and the refusals of the slide tool
		[OpenTpwText.PoolRowSlide] = new[] { "Water slide track", "Vandrutsjebane", "Glijbaan aanleggen", "Piste de toboggan", "Wasserrutsche bauen", "물 미끄럼틀 트랙", "Tor zjeżdżalni", "Pista de tobogán", "Vattenrutschkana" },
		[OpenTpwText.PoolSlideHint] = new[] { "Water slide: click or drag over the cells beside the tower; end over the pool. Backspace takes back a piece, right click stops.", "Vandrutsjebane: klik eller træk over felterne ved siden af tårnet; slut over poolen. Backspace tager et stykke tilbage, højreklik stopper.", "Glijbaan: klik of sleep over de vakjes naast de toren; eindig boven het zwembad. Backspace neemt een stuk terug, rechtsklik stopt.", "Toboggan : cliquez ou faites glisser sur les cases à côté de la tour ; terminez au-dessus de la piscine. Retour arrière reprend un élément, clic droit arrête.", "Wasserrutsche: Klicken oder ziehen Sie über die Felder neben dem Turm; enden Sie über dem Pool. Rücktaste nimmt ein Teil zurück, Rechtsklick beendet.", "물 미끄럼틀: 탑 옆 칸을 클릭하거나 끌어서 놓고 수영장 위에서 끝내세요. Backspace는 한 조각을 되돌리고 오른쪽 클릭은 멈춥니다.", "Zjeżdżalnia: kliknij lub przeciągnij po polach obok wieży; zakończ nad basenem. Backspace cofa element, prawy przycisk kończy.", "Tobogán: haz clic o arrastra por las casillas junto a la torre; termina sobre la piscina. Retroceso quita una pieza, clic derecho para.", "Vattenrutschkana: klicka eller dra över rutorna bredvid tornet; sluta över poolen. Backsteg tar tillbaka en bit, högerklick avslutar." },
		[OpenTpwText.PoolSlideHelp] = new[] { "Click the cell beside the end of the slide to add a piece; a pool cell ends it with the splash.", "Klik på feltet ved enden af rutsjebanen for at tilføje et stykke; et poolfelt afslutter den med et plask.", "Klik op het vakje naast het eind van de glijbaan om een stuk toe te voegen; een zwembadvakje sluit af met de plons.", "Cliquez sur la case à côté de la fin du toboggan pour ajouter un élément ; une case de piscine le termine par l'éclaboussure.", "Klicken Sie auf das Feld neben dem Ende der Rutsche, um ein Teil anzufügen; ein Poolfeld beendet sie mit dem Platsch.", "미끄럼틀 끝 옆 칸을 클릭해 조각을 더하세요. 수영장 칸이 첨벙으로 끝맺습니다.", "Kliknij pole obok końca zjeżdżalni, aby dodać element; pole basenu kończy ją pluskiem.", "Haz clic en la casilla junto al final del tobogán para añadir una pieza; una casilla de piscina lo termina con el chapuzón.", "Klicka på rutan bredvid slutet av rutschkanan för att lägga till en bit; en poolruta avslutar den med plasket." },
		[OpenTpwText.PoolSlideDone] = new[] { "The water slide is finished", "Vandrutsjebanen er færdig", "De glijbaan is klaar", "Le toboggan est terminé", "Die Wasserrutsche ist fertig", "물 미끄럼틀이 완성되었습니다", "Zjeżdżalnia jest gotowa", "El tobogán está terminado", "Vattenrutschkanan är färdig" },
		[OpenTpwText.PoolSlideNoTower] = new[] { "Place a slide tower beside a pool first", "Placér først et rutsjebanetårn ved en pool", "Plaats eerst een glijbaantoren naast een zwembad", "Placez d'abord une tour de toboggan à côté d'une piscine", "Stellen Sie zuerst einen Rutschenturm neben einen Pool", "먼저 수영장 옆에 미끄럼틀 탑을 놓으세요", "Najpierw postaw wieżę zjeżdżalni obok basenu", "Primero coloca una torre de tobogán junto a una piscina", "Placera först ett rutschkanetorn bredvid en pool" },
		[OpenTpwText.PoolSlideTooSteep] = new[] { "The slide is too short for the tower's height: make it longer", "Rutsjebanen er for kort til tårnets højde: gør den længere", "De glijbaan is te kort voor de hoogte van de toren: maak hem langer", "Le toboggan est trop court pour la hauteur de la tour : allongez-le", "Die Rutsche ist für die Turmhöhe zu kurz: machen Sie sie länger", "미끄럼틀이 탑 높이에 비해 너무 짧습니다. 더 길게 만드세요", "Zjeżdżalnia jest za krótka jak na wysokość wieży: wydłuż ją", "El tobogán es demasiado corto para la altura de la torre: hazlo más largo", "Rutschkanan är för kort för tornets höjd: gör den längre" },
		[OpenTpwText.PoolSlideTooGentle] = new[] { "The slide is too long for the tower's height: shorten it", "Rutsjebanen er for lang til tårnets højde: gør den kortere", "De glijbaan is te lang voor de hoogte van de toren: maak hem korter", "Le toboggan est trop long pour la hauteur de la tour : raccourcissez-le", "Die Rutsche ist für die Turmhöhe zu lang: kürzen Sie sie", "미끄럼틀이 탑 높이에 비해 너무 깁니다. 더 짧게 만드세요", "Zjeżdżalnia jest za długa jak na wysokość wieży: skróć ją", "El tobogán es demasiado largo para la altura de la torre: acórtalo", "Rutschkanan är för lång för tornets höjd: korta den" },
		[OpenTpwText.PoolSlideTooLow] = new[] { "The slide would touch the ground here", "Rutsjebanen ville røre jorden her", "De glijbaan zou hier de grond raken", "Le toboggan toucherait le sol ici", "Die Rutsche würde hier den Boden berühren", "미끄럼틀이 여기서 땅에 닿습니다", "Zjeżdżalnia dotknęłaby tu ziemi", "El tobogán tocaría el suelo aquí", "Rutschkanan skulle nudda marken här" },
		[OpenTpwText.PoolSlideNotNext] = new[] { "Continue the slide on a cell beside its end", "Fortsæt rutsjebanen på et felt ved siden af enden", "Ga verder op een vakje naast het eind van de glijbaan", "Continuez le toboggan sur une case à côté de son extrémité", "Setzen Sie die Rutsche auf einem Feld neben ihrem Ende fort", "미끄럼틀 끝 옆 칸에서 이어 가세요", "Kontynuuj zjeżdżalnię na polu obok jej końca", "Continúa el tobogán en una casilla junto a su final", "Fortsätt rutschkanan på en ruta bredvid slutet" },
		[OpenTpwText.PoolSlideNotPool] = new[] { "The slide must end over the tower's own pool", "Rutsjebanen skal ende over tårnets egen pool", "De glijbaan moet eindigen boven het zwembad van de toren", "Le toboggan doit finir au-dessus de la piscine de la tour", "Die Rutsche muss über dem Pool des Turms enden", "미끄럼틀은 탑과 이어진 수영장 위에서 끝나야 합니다", "Zjeżdżalnia musi kończyć się nad basenem wieży", "El tobogán debe terminar sobre la piscina de la torre", "Rutschkanan måste sluta över tornets egen pool" },
		[OpenTpwText.PoolSlideBadStart] = new[] { "Start the slide on a cell beside the tower, not on the stairs' side", "Start rutsjebanen på et felt ved tårnet, ikke på trappesiden", "Begin de glijbaan op een vakje naast de toren, niet aan de kant van de trap", "Commencez le toboggan sur une case à côté de la tour, pas du côté de l'escalier", "Beginnen Sie die Rutsche auf einem Feld neben dem Turm, nicht auf der Treppenseite", "탑 옆 칸에서 시작하세요. 계단 쪽은 안 됩니다", "Zacznij zjeżdżalnię na polu obok wieży, nie od strony schodów", "Empieza el tobogán en una casilla junto a la torre, no del lado de las escaleras", "Börja rutschkanan på en ruta bredvid tornet, inte på trappsidan" },
		[OpenTpwText.PoolSlideTowerNeedsPool] = new[] { "A slide tower must stand beside a pool", "Et rutsjebanetårn skal ligge ved siden af en pool", "Een glijbaantoren moet naast een zwembad staan", "Une tour de toboggan doit se trouver à côté d'une piscine", "Ein Rutschenturm muss neben einem Pool stehen", "미끄럼틀 탑은 수영장 옆에 있어야 합니다", "Wieża zjeżdżalni musi stać obok basenu", "Una torre de tobogán debe estar junto a una piscina", "Ett rutschkanetorn måste stå bredvid en pool" },
		[OpenTpwText.PoolSlideTowerFacesAway] = new[] { "Turn the slide tower: its stairs must face the pool", "Drej rutsjebanetårnet: trappen skal vende mod poolen", "Draai de glijbaantoren: de trap moet naar het zwembad kijken", "Tournez la tour de toboggan : son escalier doit faire face à la piscine", "Drehen Sie den Rutschenturm: Seine Treppe muss zum Pool zeigen", "탑을 돌리세요. 계단이 수영장을 향해야 합니다", "Obróć wieżę zjeżdżalni: schody muszą być zwrócone do basenu", "Gira la torre del tobogán: sus escaleras deben mirar a la piscina", "Vrid rutschkanetornet: trappan måste vetta mot poolen" },
		[OpenTpwText.PoolSlideWaterNeeded] = new[] { "A slide needs this pool water", "En rutsjebane har brug for dette poolvand", "Een glijbaan heeft dit zwembadwater nodig", "Un toboggan a besoin de cette eau de piscine", "Eine Rutsche braucht dieses Poolwasser", "미끄럼틀에 이 수영장 물이 필요합니다", "Zjeżdżalnia potrzebuje tej wody basenowej", "Un tobogán necesita esta agua de piscina", "En rutschkana behöver det här poolvattnet" },
