		[OpenTpwText.PoolRowRiver] = new[] { "Lazy river water", "Doven flod", "Lazy river", "Rivière paresseuse", "Lazy River", "느린 강", "Leniwa rzeka", "Río lento", "Lat flod" },
		[OpenTpwText.PoolRiverHelp] = new[] { "Click and drag to paint a ring of river water; its current carries swimmers round.", "Klik og træk for at male en ring af flodvand; strømmen fører svømmerne rundt.", "Klik en sleep om een ring rivierwater te schilderen; de stroming voert zwemmers rond.", "Cliquez et faites glisser pour peindre un anneau de rivière ; le courant emporte les nageurs.", "Klicken und ziehen, um einen Ring aus Flusswasser zu malen; die Strömung trägt Schwimmer herum.", "클릭하고 끌어서 강물 고리를 칠하십시오. 물살이 수영객을 실어 나릅니다.", "Kliknij i przeciągnij, aby namalować pierścień wody rzecznej; nurt niesie pływaków.", "Haz clic y arrastra para pintar un anillo de río; la corriente lleva a los nadadores.", "Klicka och dra för att måla en ring av flodvatten; strömmen bär simmarna runt." },
		[OpenTpwText.PoolRiverHint] = new[] { "Lazy river: press and drag to paint a ring one cell wide; right click to stop.", "Doven flod: tryk og træk for at male en ring, en celle bred; højreklik for at stoppe.", "Lazy river: houd ingedrukt en sleep om een ring van één vakje breed te schilderen; klik met rechts om te stoppen.", "Rivière paresseuse : appuyez et faites glisser pour peindre un anneau d'une case de large ; clic droit pour arrêter.", "Lazy River: drücken und ziehen, um einen Ring von einem Feld Breite zu malen; Rechtsklick beendet.", "느린 강: 누른 채 끌어서 한 칸 너비의 고리를 칠하십시오. 오른쪽 클릭하면 멈춥니다.", "Leniwa rzeka: naciśnij i przeciągnij, aby namalować pierścień szerokości jednego pola; PPM kończy.", "Río lento: pulsa y arrastra para pintar un anillo de una casilla de ancho; clic derecho para parar.", "Lat flod: tryck och dra för att måla en ring, en ruta bred; högerklicka för att sluta." },
