		[OpenTpwText.ModBuiltIn] = new[] { "Official extension built into OpenTPW", "Officiel udvidelse indbygget i OpenTPW", "Officiële extensie die in OpenTPW is ingebouwd", "Extension officielle intégrée à OpenTPW", "Offizielle, in OpenTPW eingebaute Erweiterung", "OpenTPW에 내장된 공식 확장", "Oficjalne rozszerzenie wbudowane w OpenTPW", "Extensión oficial integrada en OpenTPW", "Officiellt tillägg som ingår i OpenTPW" },
