		[OpenTpwText.ModAffectsSimulation] = new[] { "Changes the park simulation", "Ændrer parksimuleringen", "Verandert de parksimulatie", "Modifie la simulation du parc", "Verändert die Parksimulation", "공원 시뮬레이션을 바꿉니다", "Zmienia symulację parku", "Cambia la simulación del parque", "Ändrar parksimuleringen" },
		// [EXT:smarter-guests] the names and descriptions of the two guest extensions (docs/SMARTER-GUESTS.md)
		[OpenTpwText.ExtensionSmarterGuestsName] = new[] { "Smarter guests", "Klogere gæster", "Slimmere gasten", "Visiteurs plus malins", "Klügere Gäste", "더 똑똑한 손님", "Mądrzejsi goście", "Visitantes más listos", "Smartare gäster" },
		[OpenTpwText.ExtensionSmarterGuestsDescription] = new[] { "Guests make better choices: they weigh prices, spread over the rides, give up on queues that are far too long, plan ahead for hunger and thirst, and complain about litter and crowds. This changes the park simulation, so saved parks remember it, and a park saved with it only opens with it, in the same version. Off by default.", "Gæsterne træffer bedre valg: de vejer priser, fordeler sig over forlystelserne, giver op i alt for lange køer, planlægger efter sult og tørst og klager over affald og trængsel. Det ændrer parkens simulation, så gemte parker husker det, og en park gemt med det åbner kun med det, i samme version. Slået fra som standard.", "Gasten maken betere keuzes: ze wegen prijzen af, verdelen zich over de attracties, geven het op in veel te lange wachtrijen, plannen vooruit voor honger en dorst en klagen over rommel en drukte. Dit verandert de simulatie van het park, dus opgeslagen parken onthouden het, en een park dat ermee is opgeslagen opent alleen ermee, in dezelfde versie. Standaard uit.", "Les visiteurs font de meilleurs choix : ils comparent les prix, se répartissent entre les attractions, renoncent aux files beaucoup trop longues, anticipent la faim et la soif et se plaignent des détritus et de la foule. Cela change la simulation du parc, donc les parcs enregistrés s'en souviennent, et un parc enregistré avec cette extension ne s'ouvre qu'avec elle, dans la même version. Désactivé par défaut.", "Gäste treffen bessere Entscheidungen: Sie wägen Preise ab, verteilen sich auf die Fahrgeschäfte, geben bei viel zu langen Warteschlangen auf, planen Hunger und Durst voraus und beschweren sich über Müll und Gedränge. Das ändert die Simulation des Parks, daher merken sich gespeicherte Parks es, und ein damit gespeicherter Park lässt sich nur damit öffnen, in derselben Version. Standardmäßig aus.", "손님이 더 좋은 선택을 합니다. 가격을 따져 보고, 놀이기구에 고르게 나뉘고, 너무 긴 줄은 포기하고, 배고픔과 목마름을 미리 챙기고, 쓰레기와 혼잡에 불평합니다. 공원 시뮬레이션이 바뀌므로 저장한 공원이 이 설정을 기억하며, 이 확장으로 저장한 공원은 같은 버전의 이 확장으로만 열립니다. 기본값은 꺼짐입니다.", "Goście dokonują lepszych wyborów: porównują ceny, rozkładają się na atrakcje, rezygnują ze zdecydowanie za długich kolejek, planują z wyprzedzeniem głód i pragnienie oraz narzekają na śmieci i tłok. Zmienia to symulację parku, więc zapisane parki to pamiętają, a park zapisany z tym rozszerzeniem otworzy się tylko z nim, w tej samej wersji. Domyślnie wyłączone.", "Los visitantes eligen mejor: comparan precios, se reparten entre las atracciones, abandonan colas demasiado largas, se anticipan al hambre y la sed y se quejan de la basura y las aglomeraciones. Esto cambia la simulación del parque, así que los parques guardados lo recuerdan, y un parque guardado con esta extensión solo se abre con ella, en la misma versión. Desactivado por defecto.", "Gäster gör bättre val: de väger priser, sprider sig över attraktionerna, ger upp i alldeles för långa köer, planerar i förväg för hunger och törst och klagar på skräp och trängsel. Det ändrar parkens simulering, så sparade parker kommer ihåg det, och en park som sparats med den öppnas bara med den, i samma version. Av som standard." },
		[OpenTpwText.RefusalsTitle] = new[] { "Why guests said no", "Hvorfor gæster sagde nej", "Waarom gasten nee zeiden", "Pourquoi les visiteurs refusent", "Warum Gäste ablehnten", "손님이 거절한 이유", "Dlaczego goście odmówili", "Por qué los visitantes rechazaron", "Varför gäster sa nej" },
		[OpenTpwText.RefusalTooExpensive] = new[] { "Too expensive", "For dyrt", "Te duur", "Trop cher", "Zu teuer", "너무 비쌈", "Za drogo", "Demasiado caro", "För dyrt" },
		[OpenTpwText.RefusalQueueTooLong] = new[] { "Queue too long", "Køen er for lang", "Wachtrij te lang", "File trop longue", "Schlange zu lang", "줄이 너무 김", "Za długa kolejka", "Cola demasiado larga", "Kön är för lång" },
		[OpenTpwText.RefusalTooScary] = new[] { "Too scary", "For skræmmende", "Te eng", "Trop effrayant", "Zu beängstigend", "너무 무서움", "Zbyt straszne", "Demasiado aterrador", "För läskigt" },
		[OpenTpwText.RefusalTooBoring] = new[] { "Too boring", "For kedeligt", "Te saai", "Trop ennuyeux", "Zu langweilig", "너무 지루함", "Zbyt nudne", "Demasiado aburrido", "För tråkigt" },
		[OpenTpwText.RefusalRideUnavailable] = new[] { "Ride broken or closed", "Forlystelse i stykker eller lukket", "Attractie kapot of gesloten", "Attraction en panne ou fermée", "Fahrgeschäft defekt oder geschlossen", "놀이기구 고장 또는 닫힘", "Atrakcja zepsuta lub zamknięta", "Atracción averiada o cerrada", "Åkattraktion trasig eller stängd" },
		[OpenTpwText.ExtensionGuestInsightsName] = new[] { "Guest insights", "Gæsteindsigt", "Gastinzichten", "Suivi des visiteurs", "Gäste-Einblicke", "손님 분석", "Informacje o gościach", "Información de visitantes", "Gästinsikter" },
		[OpenTpwText.ExtensionGuestInsightsDescription] = new[] { "Counts why guests turn down rides and shops and shows the totals in the park information window. Display only: it never changes the simulation or your saves.", "Tæller hvorfor gæster afviser forlystelser og butikker og viser totalerne i parkinformationsvinduet. Kun visning: ændrer aldrig simuleringen eller dine gemte parker.", "Telt waarom gasten attracties en winkels afwijzen en toont de totalen in het parkinformatievenster. Alleen weergave: verandert nooit de simulatie of je opgeslagen parken.", "Compte pourquoi les visiteurs refusent attractions et boutiques et affiche les totaux dans la fenêtre d'information du parc. Affichage seul : ne modifie jamais la simulation ni vos sauvegardes.", "Zählt, warum Gäste Fahrgeschäfte und Läden ablehnen, und zeigt die Summen im Parkinformationsfenster. Nur Anzeige: ändert nie die Simulation oder deine Spielstände.", "손님이 놀이기구와 상점을 거절하는 이유를 세어 공원 정보 창에 합계를 보여 줍니다. 표시 전용이며 시뮬레이션과 저장 파일을 바꾸지 않습니다.", "Liczy, dlaczego goście odmawiają atrakcji i sklepów, i pokazuje sumy w oknie informacji o parku. Tylko wyświetlanie: nigdy nie zmienia symulacji ani zapisów.", "Cuenta por qué los visitantes rechazan atracciones y tiendas y muestra los totales en la ventana de información del parque. Solo visualización: nunca cambia la simulación ni tus partidas guardadas.", "Räknar varför gäster tackar nej till attraktioner och butiker och visar summorna i parkinformationsfönstret. Endast visning: ändrar aldrig simuleringen eller dina sparade parker." },
		[OpenTpwText.ExtensionPoolGuestArtName] = new[] { "Pool guest art", "Pool-gæstegrafik", "Zwembadgasten-graphics", "Visiteurs de la piscine", "Poolgast-Grafik", "수영장 손님 그래픽", "Grafika gości basenu", "Arte de los visitantes de la piscina", "Poolgästgrafik" },
		[OpenTpwText.ExtensionPoolGuestArtDescription] = new[] { "With the Pools extension on, guests on land are drawn with OpenTPW's own high-resolution kids in their clothes, and in swimwear in the water. Turn it off to see the original guests on land (swimmers keep their swimwear). Display only: it never changes the simulation or your saves.", "Når Pools-udvidelsen er slået til, tegnes gæster på land med OpenTPW's egne højopløselige børn i deres tøj, og i badetøj i vandet. Slå fra for at se de originale gæster på land (svømmerne beholder deres badetøj). Kun visning: ændrer aldrig simuleringen eller dine gemte parker.", "Met de uitbreiding Zwembaden aan worden gasten op het land getekend met OpenTPW's eigen kinderen in hoge resolutie in hun kleren, en in zwemkleding in het water. Zet uit om de originele gasten op het land te zien (zwemmers houden hun zwemkleding). Alleen weergave: verandert nooit de simulatie of je opgeslagen parken.", "Avec l'extension Piscines activée, les visiteurs à terre sont dessinés avec les enfants haute résolution d'OpenTPW en vêtements, et en maillot dans l'eau. Désactivez pour voir les visiteurs d'origine à terre (les nageurs gardent leur maillot). Affichage seul : ne modifie jamais la simulation ni vos sauvegardes.", "Bei aktivierter Pools-Erweiterung werden Gäste an Land mit OpenTPWs eigenen hochauflösenden Kindern in Kleidung gezeichnet, im Wasser in Badekleidung. Ausschalten zeigt die Originalgäste an Land (Schwimmer behalten ihre Badekleidung). Nur Anzeige: ändert nie die Simulation oder deine Spielstände.", "수영장 확장이 켜져 있으면 육지의 손님은 OpenTPW의 고해상도 어린이 옷차림으로, 물속에서는 수영복 차림으로 그려집니다. 끄면 육지에서 원래 손님이 보입니다(수영하는 손님은 수영복 유지). 표시 전용이며 시뮬레이션과 저장 파일을 바꾸지 않습니다.", "Gdy rozszerzenie Baseny jest włączone, goście na lądzie są rysowani własnymi dzieciakami OpenTPW w wysokiej rozdzielczości w ubraniach, a w wodzie w strojach kąpielowych. Wyłącz, aby zobaczyć oryginalnych gości na lądzie (pływacy zachowują stroje). Tylko wyświetlanie: nigdy nie zmienia symulacji ani zapisów.", "Con la extensión Piscinas activada, los visitantes en tierra se dibujan con los niños de alta resolución de OpenTPW con su ropa, y en bañador en el agua. Desactívala para ver los visitantes originales en tierra (los nadadores conservan el bañador). Solo visualización: nunca cambia la simulación ni tus partidas guardadas.", "Med tillägget Pooler på ritas gäster på land med OpenTPW:s egna högupplösta barn i sina kläder, och i badkläder i vattnet. Stäng av för att se originalgästerna på land (badare behåller badkläderna). Endast visning: ändrar aldrig simuleringen eller dina sparade parker." },
		[OpenTpwText.ExtensionRestoredAdviceName] = new[] { "Restored advice", "Genoprettede råd", "Herstelde adviezen", "Conseils restaurés", "Wiederhergestellte Hinweise", "복원된 조언", "Przywrócone porady", "Consejos restaurados", "Återställda råd" },
		[OpenTpwText.ExtensionRestoredAdviceDescription] = new[] { "The advisor says lines the original game never plays: security gaps, long queues, blocked ride exits, riders stuck in broken rides, arriving buses, planes and boats, golden ticket news and more. Advice only: it never changes the simulation or your saves.", "Rådgiveren siger replikker, som det originale spil aldrig afspiller: huller i sikkerheden, lange køer, blokerede udgange, gæster fast i defekte forlystelser, ankomne busser, fly og både, nyt om guldbilletter og mere. Kun råd: ændrer aldrig simuleringen eller dine gemte parker.", "De adviseur zegt zinnen die het originele spel nooit afspeelt: gaten in de beveiliging, lange wachtrijen, geblokkeerde uitgangen, gasten vast in kapotte attracties, aankomende bussen, vliegtuigen en boten, nieuws over gouden tickets en meer. Alleen advies: verandert nooit de simulatie of je opgeslagen parken.", "Le conseiller dit des phrases que le jeu d'origine ne joue jamais : trous dans la sécurité, files trop longues, sorties bloquées, visiteurs coincés dans des attractions en panne, bus, avions et bateaux qui arrivent, nouvelles des billets d'or et plus. Conseils seuls : ne modifie jamais la simulation ni vos sauvegardes.", "Der Berater sagt Sätze, die das Originalspiel nie abspielt: Lücken in der Sicherheit, lange Schlangen, blockierte Ausgänge, Gäste in defekten Fahrgeschäften, ankommende Busse, Flugzeuge und Boote, Neuigkeiten zu goldenen Tickets und mehr. Nur Hinweise: ändert nie die Simulation oder deine Spielstände.", "원래 게임에서는 나오지 않던 조언자의 대사를 들려줍니다. 경비 사각지대, 긴 줄, 막힌 출구, 고장 난 놀이기구에 갇힌 손님, 도착한 버스와 비행기와 배, 황금 티켓 소식 등. 조언만 하며 시뮬레이션과 저장 파일을 바꾸지 않습니다.", "Doradca mówi kwestie, których oryginalna gra nigdy nie odtwarza: luki w ochronie, długie kolejki, zablokowane wyjścia, goście uwięzieni w zepsutych atrakcjach, przyjeżdżające autobusy, samoloty i łodzie, wieści o złotych biletach i więcej. Tylko porady: nigdy nie zmienia symulacji ani zapisów.", "El asesor dice frases que el juego original nunca reproduce: huecos en la seguridad, colas largas, salidas bloqueadas, visitantes atrapados en atracciones averiadas, autobuses, aviones y barcos que llegan, noticias de billetes dorados y más. Solo consejos: nunca cambia la simulación ni tus partidas guardadas.", "Rådgivaren säger repliker som originalspelet aldrig spelar upp: luckor i säkerheten, långa köer, blockerade utgångar, gäster som sitter fast i trasiga attraktioner, ankommande bussar, flygplan och båtar, nyheter om guldbiljetter och mer. Endast råd: ändrar aldrig simuleringen eller dina sparade parker." },
		[OpenTpwText.ModLeavesSimulation] = new[] { "Does not change the park simulation", "Ændrer ikke parksimuleringen", "Verandert de parksimulatie niet", "Ne modifie pas la simulation du parc", "Verändert die Parksimulation nicht", "공원 시뮬레이션을 바꾸지 않습니다", "Nie zmienia symulacji parku", "No cambia la simulación del parque", "Ändrar inte parksimuleringen" },
