		[OpenTpwText.ModInputNotFound] = new[] { "No game data folder found here", "Ingen mappe med spildata fundet her", "Hier is geen map met spelgegevens gevonden", "Aucun dossier de données du jeu trouvé ici", "Hier wurde kein Spieldatenordner gefunden", "여기에는 게임 데이터 폴더가 없습니다", "Nie znaleziono tu folderu z danymi gry", "No hay carpeta de datos del juego aquí", "Ingen mapp med speldata hittades här" },
