		[OpenTpwText.TpiGuestsInPark] = new[] { "Guests in park: {0}", "Gaester i parken: {0}", "Bezoekers in park: {0}", "Visiteurs dans le parc : {0}", "Besucher im Park: {0}", "공원 손님: {0}", "Goście w parku: {0}", "Visitantes en el parque: {0}", "Gäster i parken: {0}" },
		[OpenTpwText.TpiRemove] = new[] { "Remove", "Fjern", "Verwijderen", "Retirer", "Entfernen", "제거", "Usuń", "Quitar", "Ta bort" },
		[OpenTpwText.TpiRemoveHelp] = new[] { "Click park objects, queues or paths to remove them (objects refund their scrap value)", "Klik på parkobjekter, køer eller stier for at fjerne dem (objekter giver deres skrotværdi tilbage)", "Klik op parkobjecten, wachtrijen of paden om ze te verwijderen (objecten leveren hun sloopwaarde op)", "Cliquez sur des objets, files ou chemins du parc pour les retirer (les objets rapportent leur valeur de récupération)", "Klicke auf Parkobjekte, Warteschlangen oder Wege, um sie zu entfernen (Objekte erstatten ihren Schrottwert)", "공원 시설, 대기줄, 길을 클릭하면 제거됩니다 (시설은 고철 가치만큼 환불됩니다)", "Kliknij obiekty parku, kolejki lub ścieżki, aby je usunąć (obiekty zwracają wartość złomu)", "Haz clic en objetos, colas o caminos del parque para quitarlos (los objetos devuelven su valor de desguace)", "Klicka på parkobjekt, köer eller stigar för att ta bort dem (objekt ger tillbaka sitt skrotvärde)" },
		[OpenTpwText.TpiBuild] = new[] { "Build...", "Byg...", "Bouwen...", "Construire...", "Bauen...", "건설...", "Buduj...", "Construir...", "Bygg..." },
		[OpenTpwText.TpiBuildHelp] = new[] { "Open the world's object catalogue (each object costs its purchase price)", "Åbn verdenens objektkatalog (hvert objekt koster sin købspris)", "Open de objectencatalogus van de wereld (elk object kost zijn aankoopprijs)", "Ouvrir le catalogue d'objets du monde (chaque objet coûte son prix d'achat)", "Den Objektkatalog der Welt öffnen (jedes Objekt kostet seinen Kaufpreis)", "월드의 시설 목록을 엽니다 (시설마다 구입 가격이 듭니다)", "Otwórz katalog obiektów świata (każdy obiekt kosztuje swoją cenę zakupu)", "Abrir el catálogo de objetos del mundo (cada objeto cuesta su precio de compra)", "Öppna världens objektkatalog (varje objekt kostar sitt inköpspris)" },
		[OpenTpwText.TpiRotate] = new[] { "Rotate", "Drej", "Draaien", "Pivoter", "Drehen", "회전", "Obróć", "Girar", "Rotera" },
